dashboard.definition:
{
  "title": "Homelab Security",
  "description": "ATT&CK v20 findings, fired alerts, Falco, the honeypot, logins, the Kubernetes API, Vault and the MCP gateway, and detection health.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {}
        }
      }
    }
  },
  "visualizations": {
    "viz_h_status": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Status\nCounts for the selected time range; red means anything to look at.",
        "fontSize": "default"
      }
    },
    "viz_t_findings": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_findings"
      },
      "title": "Detection findings",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()"
      }
    },
    "viz_t_findings_hi": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_findings_hi"
      },
      "title": "Findings: critical or high",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_t_falco_hi": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_falco_hi"
      },
      "title": "Falco: high or critical",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_t_canary": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_canary"
      },
      "title": "Honeypot connections",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_t_auth_fail": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_auth_fail"
      },
      "title": "Failed logins",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_t_mcp_denied": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_mcp_denied"
      },
      "title": "MCP calls denied",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_h_findings": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Detection findings (ATT&CK v20)\nFrom the HL detections in `85_detections`: `index=security sourcetype=homelab:detection`, the queue the security agent reads.",
        "fontSize": "default"
      }
    },
    "viz_f_time": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_f_over_time"
      },
      "title": "Findings by severity",
      "options": {
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "events",
        "legendDisplay": "right",
        "seriesColorsByField": {
          "critical": "#D41F1F",
          "high": "#EC9960",
          "medium": "#F8BE34",
          "low": "#7B98BD",
          "informational": "#A7A9AC"
        }
      }
    },
    "viz_f_tech": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_f_by_technique"
      },
      "title": "By ATT&CK tactic and technique",
      "options": {
        "count": 20
      }
    },
    "viz_f_recent": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_f_recent"
      },
      "title": "Findings, most severe first",
      "options": {
        "count": 20
      }
    },
    "viz_h_alerts": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Fired alerts\nEvery alert from the detections, Falco, honeypot and secret-leak apps.",
        "fontSize": "default"
      }
    },
    "viz_alerts": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_alerts_fired"
      },
      "title": "Alerts fired",
      "options": {
        "count": 20
      }
    },
    "viz_h_falco": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Falco runtime",
        "fontSize": "large"
      }
    },
    "viz_falco_time": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_falco_over_time"
      },
      "title": "Falco events by severity",
      "options": {
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "events",
        "legendDisplay": "right",
        "seriesColorsByField": {
          "critical": "#D41F1F",
          "high": "#EC9960",
          "medium": "#F8BE34",
          "low": "#7B98BD",
          "informational": "#A7A9AC"
        }
      }
    },
    "viz_falco_rules": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_falco_rules"
      },
      "title": "Rules, most severe first",
      "options": {
        "count": 20
      }
    },
    "viz_falco_recent": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_falco_recent"
      },
      "title": "Medium and above, most severe first",
      "options": {
        "count": 20
      }
    },
    "viz_h_canary": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Honeypot (OpenCanary, 192.168.4.240)\nNothing should ever connect to it.",
        "fontSize": "default"
      }
    },
    "viz_canary": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_canary"
      },
      "title": "Connections by source",
      "options": {
        "count": 20
      }
    },
    "viz_h_auth": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Logins\nTailscale SSH, OpenSSH, sudo, Proxmox and UniFi admin, via CIM tag=authentication.",
        "fontSize": "default"
      }
    },
    "viz_auth_time": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_auth_over_time"
      },
      "title": "Logins by method and result",
      "options": {
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "events",
        "legendDisplay": "right"
      }
    },
    "viz_auth_src": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_auth_sources"
      },
      "title": "Who logged in from where (failures first)",
      "options": {
        "count": 20
      }
    },
    "viz_h_k8s": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Kubernetes API (k3s-01)\nAudit log. Platform controllers (`hl_k8s_platform_user`) are left out of the writes table.",
        "fontSize": "default"
      }
    },
    "viz_k8s_denied": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_k8s_denied"
      },
      "title": "Unauthenticated (401) and forbidden (403) requests",
      "options": {
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleText": "events",
        "legendDisplay": "right"
      }
    },
    "viz_k8s_denied_tbl": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_k8s_denied_tbl"
      },
      "title": "401 and 403 by caller",
      "options": {
        "count": 20
      }
    },
    "viz_k8s_writes": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_k8s_people_writes"
      },
      "title": "Changes made by people and apps",
      "options": {
        "count": 20
      }
    },
    "viz_h_vault": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Vault",
        "fontSize": "large"
      }
    },
    "viz_vault_ids": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_vault_identities"
      },
      "title": "Requests by identity",
      "options": {
        "count": 20
      }
    },
    "viz_vault_err": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_vault_errors"
      },
      "title": "Errors (denied or failed requests)",
      "options": {
        "count": 20
      }
    },
    "viz_h_mcp": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## MCP gateway (mcp.bmosan.com)",
        "fontSize": "large"
      }
    },
    "viz_mcp_clients": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_mcp_clients"
      },
      "title": "Tool calls by client",
      "options": {
        "count": 20
      }
    },
    "viz_mcp_denied": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_mcp_denied"
      },
      "title": "Denied or failed calls",
      "options": {
        "count": 20
      }
    },
    "viz_h_health": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## Detection health (last 24 hours)\nEvery scheduled search in the detection, Falco, honeypot and secret-leak apps, and whether it ran.",
        "fontSize": "default"
      }
    },
    "viz_t_det": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_t_det_unhealthy"
      },
      "title": "Searches not running cleanly",
      "options": {
        "majorValue": "> primary | seriesByIndex(0) | lastPoint()",
        "majorColor": "> majorValue | rangeValue(colors)"
      },
      "context": {
        "colors": [
          {
            "to": 0.5,
            "value": "#118832"
          },
          {
            "from": 0.5,
            "value": "#D41F1F"
          }
        ]
      }
    },
    "viz_det_health": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_det_health"
      },
      "title": "Scheduled searches",
      "options": {
        "count": 20
      }
    }
  },
  "dataSources": {
    "ds_t_findings": {
      "type": "ds.search",
      "name": "t_findings",
      "options": {
        "query": "index=security sourcetype=homelab:detection | eval host=mvindex(host, 0) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_t_findings_hi": {
      "type": "ds.search",
      "name": "t_findings_hi",
      "options": {
        "query": "index=security sourcetype=homelab:detection | eval host=mvindex(host, 0) | search severity IN (critical, high) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_t_falco_hi": {
      "type": "ds.search",
      "name": "t_falco_hi",
      "options": {
        "query": "index=security sourcetype=falco:ocsf severity IN (high, critical) | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_t_canary": {
      "type": "ds.search",
      "name": "t_canary",
      "options": {
        "query": "index=security sourcetype=opencanary logtype>=2000 | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_t_auth_fail": {
      "type": "ds.search",
      "name": "t_auth_fail",
      "options": {
        "query": "index IN (infra, audit) tag=authentication action=failure | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_t_mcp_denied": {
      "type": "ds.search",
      "name": "t_mcp_denied",
      "options": {
        "query": "index=audit sourcetype=toolhive:vmcp:audit | eval client=replace('subjects.user_id', \"^system:serviceaccount:toolhive-clients:\", \"\"), tool='target.name' | search outcome=denied | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_f_over_time": {
      "type": "ds.search",
      "name": "f_over_time",
      "options": {
        "query": "index=security sourcetype=homelab:detection | eval host=mvindex(host, 0) | timechart count by severity",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_f_by_technique": {
      "type": "ds.search",
      "name": "f_by_technique",
      "options": {
        "query": "index=security sourcetype=homelab:detection | eval host=mvindex(host, 0) | stats count latest(_time) as last values(detection) as Detections by tactic technique | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename tactic as Tactic technique as Technique count as Findings | table Tactic Technique Detections Findings When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_f_recent": {
      "type": "ds.search",
      "name": "f_recent",
      "options": {
        "query": "index=security sourcetype=homelab:detection | eval host=mvindex(host, 0) | eval sev_rank=case(severity==\"critical\",1, severity==\"high\",2, severity==\"medium\",3, severity==\"low\",4, true(),5) | sort sev_rank - _time | head 200 | eval Time=strftime(_time, \"%Y-%m-%d %H:%M\"), detail=substr(detail, 1, 200) | rename severity as Severity detection as Detection technique as Technique host as Host user as User src as Source object as Object detail as Detail | table Time Severity Detection Technique Host User Source Object Detail",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_alerts_fired": {
      "type": "ds.search",
      "name": "alerts_fired",
      "options": {
        "query": "index=_audit action=alert_fired ss_app IN (85_detections, 85_falco, 85_opencanary, 85_secret_leaks) | stats count latest(_time) as last by ss_app ss_name severity | eval Severity=case(severity==5,\"critical\", severity==4,\"high\", severity==3,\"medium\", severity==2,\"low\", true(),\"info\") | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename ss_name as Alert ss_app as App count as Fired | table Alert App Severity Fired When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_falco_over_time": {
      "type": "ds.search",
      "name": "falco_over_time",
      "options": {
        "query": "index=security sourcetype=falco:ocsf | timechart count by severity",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_falco_rules": {
      "type": "ds.search",
      "name": "falco_rules",
      "options": {
        "query": "index=security sourcetype=falco:ocsf | rename finding_info.title as rule | stats count dc(host) as hosts values(host) as Hosts latest(_time) as last by rule severity | eval sev_rank=case(severity==\"critical\",1, severity==\"high\",2, severity==\"medium\",3, severity==\"low\",4, true(),5) | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort sev_rank - count | rename rule as Rule severity as Severity count as Events | table Severity Rule Events Hosts When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_falco_recent": {
      "type": "ds.search",
      "name": "falco_recent",
      "options": {
        "query": "index=security sourcetype=falco:ocsf severity IN (medium, high, critical) | eval sev_rank=case(severity==\"critical\",1, severity==\"high\",2, severity==\"medium\",3, severity==\"low\",4, true(),5) | sort sev_rank - _time | head 100 | eval Time=strftime(_time, \"%Y-%m-%d %H:%M\"), Detail=substr(message, 1, 220) | rename severity as Severity finding_info.title as Rule host as Host | table Time Severity Rule Host Detail",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_canary": {
      "type": "ds.search",
      "name": "canary",
      "options": {
        "query": "index=security sourcetype=opencanary logtype>=2000 | stats count min(_time) as first latest(_time) as last values(signature) as Activity values(dest_port) as Ports values(user) as Usernames by src | eval \"First seen\"=strftime(first, \"%Y-%m-%d %H:%M\") | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename src as Source count as Events | table Source Activity Ports Usernames Events \"First seen\" When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_auth_over_time": {
      "type": "ds.search",
      "name": "auth_over_time",
      "options": {
        "query": "index IN (infra, audit) tag=authentication action IN (success, failure) app=* | eval series=app.\" \".action | timechart usenull=f count by series",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_auth_sources": {
      "type": "ds.search",
      "name": "auth_sources",
      "options": {
        "query": "index IN (infra, audit) tag=authentication action IN (success, failure) | stats count(eval(action==\"success\")) as Successes count(eval(action==\"failure\")) as Failures dc(dest) as hosts values(dest) as Targets latest(_time) as last by app user src | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - Failures - last | rename app as Method user as User src as Source | table Method User Source Targets Successes Failures When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_k8s_denied": {
      "type": "ds.search",
      "name": "k8s_denied",
      "options": {
        "query": "`hl_k8s_audit` | where 'responseStatus.code'==401 OR 'responseStatus.code'==403 | eval code='responseStatus.code' | timechart count by code",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_k8s_people_writes": {
      "type": "ds.search",
      "name": "k8s_people_writes",
      "options": {
        "query": "`hl_k8s_audit` verb IN (create, update, patch, delete, deletecollection) | where NOT `hl_k8s_platform_user` | eval resource='objectRef.resource'.if(isnotnull('objectRef.subresource'), \"/\".'objectRef.subresource', \"\") | rename objectRef.name as obj_name objectRef.namespace as ns user.username as who | stats count latest(_time) as last values(obj_name) as Names by who verb resource ns | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename who as User verb as Verb resource as Resource ns as Namespace count as Requests | eval Names=mvjoin(mvindex(Names, 0, 4), \", \") | table User Verb Resource Namespace Names Requests When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_k8s_denied_tbl": {
      "type": "ds.search",
      "name": "k8s_denied_tbl",
      "options": {
        "query": "`hl_k8s_audit` | where 'responseStatus.code'==401 OR 'responseStatus.code'==403 | eval user=coalesce('user.username', \"(unauthenticated)\"), src=mvindex('sourceIPs{}', 0), code='responseStatus.code', res='objectRef.resource' | stats count latest(_time) as last values(verb) as Verbs values(res) as Resources by user src code | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - count | rename user as User src as Source code as Code count as Requests | table User Source Code Verbs Resources Requests When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_vault_identities": {
      "type": "ds.search",
      "name": "vault_identities",
      "options": {
        "query": "`hl_vault_audit` | eval who=coalesce('auth.display_name', \"(no token)\"), status=if(isnotnull(error), \"error\", \"ok\"), op='request.operation', path='request.path' | stats count(eval(status==\"ok\")) as OK count(eval(status==\"error\")) as Errors values(op) as Operations dc(path) as Paths latest(_time) as last by who | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - Errors - OK | rename who as Identity | table Identity Operations Paths OK Errors When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_vault_errors": {
      "type": "ds.search",
      "name": "vault_errors",
      "options": {
        "query": "`hl_vault_audit` error=* | eval who=coalesce('auth.display_name', \"(no token)\"), op='request.operation', path='request.path' | stats count latest(_time) as last values(error) as Error by who path op | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename who as Identity path as Path op as Operation count as Requests | table Identity Operation Path Error Requests When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_mcp_clients": {
      "type": "ds.search",
      "name": "mcp_clients",
      "options": {
        "query": "index=audit sourcetype=toolhive:vmcp:audit | eval client=replace('subjects.user_id', \"^system:serviceaccount:toolhive-clients:\", \"\"), tool='target.name' | search NOT tool IN (initialized, gw-probe) | stats count(eval(outcome==\"success\")) as OK count(eval(outcome==\"denied\")) as Denied count(eval(outcome==\"failure\")) as Failed dc(tool) as Tools latest(_time) as last by client | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - Denied - OK | rename client as Client | table Client Tools OK Denied Failed When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_mcp_denied": {
      "type": "ds.search",
      "name": "mcp_denied",
      "options": {
        "query": "index=audit sourcetype=toolhive:vmcp:audit | eval client=replace('subjects.user_id', \"^system:serviceaccount:toolhive-clients:\", \"\"), tool='target.name' | search outcome IN (denied, failure) | stats count latest(_time) as last by client tool outcome | eval When=strftime(last, \"%Y-%m-%d %H:%M\") | sort - last | rename client as Client tool as Tool outcome as Outcome count as Calls | table Client Tool Outcome Calls When",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_det_health": {
      "type": "ds.search",
      "name": "det_health",
      "options": {
        "query": "| rest /servicesNS/-/-/saved/searches splunk_server=local count=0 | search eai:acl.app IN (85_detections, 85_falco, 85_opencanary, 85_secret_leaks) is_scheduled=1 disabled=0 | rename title as savedsearch_name eai:acl.app as App | fields savedsearch_name App cron_schedule | join type=left savedsearch_name [search index=_internal sourcetype=scheduler app IN (85_detections, 85_falco, 85_opencanary, 85_secret_leaks) earliest=-24h | stats count(eval(status==\"success\")) as ok count(eval(status!=\"success\")) as not_ok latest(_time) as last avg(run_time) as rt by savedsearch_name] | fillnull value=0 ok not_ok | eval Status=case(isnull(last), \"NEVER RAN (24 h)\", not_ok>0, \"SKIPPED OR FAILED\", true(), \"ok\"), \"Last run\"=strftime(last, \"%Y-%m-%d %H:%M\"), \"Avg run (s)\"=round(rt, 1) | eval rank=if(Status==\"ok\", 1, 0) | sort rank savedsearch_name | rename savedsearch_name as Search cron_schedule as Schedule ok as Runs not_ok as \"Not run\" | table Status Search App Schedule Runs \"Not run\" \"Avg run (s)\" \"Last run\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    },
    "ds_t_det_unhealthy": {
      "type": "ds.search",
      "name": "t_det_unhealthy",
      "options": {
        "query": "| rest /servicesNS/-/-/saved/searches splunk_server=local count=0 | search eai:acl.app IN (85_detections, 85_falco, 85_opencanary, 85_secret_leaks) is_scheduled=1 disabled=0 | rename title as savedsearch_name eai:acl.app as App | fields savedsearch_name App cron_schedule | join type=left savedsearch_name [search index=_internal sourcetype=scheduler app IN (85_detections, 85_falco, 85_opencanary, 85_secret_leaks) earliest=-24h | stats count(eval(status==\"success\")) as ok count(eval(status!=\"success\")) as not_ok latest(_time) as last avg(run_time) as rt by savedsearch_name] | fillnull value=0 ok not_ok | eval Status=case(isnull(last), \"NEVER RAN (24 h)\", not_ok>0, \"SKIPPED OR FAILED\", true(), \"ok\"), \"Last run\"=strftime(last, \"%Y-%m-%d %H:%M\"), \"Avg run (s)\"=round(rt, 1) | eval rank=if(Status==\"ok\", 1, 0) | sort rank savedsearch_name | rename savedsearch_name as Search cron_schedule as Schedule ok as Runs not_ok as \"Not run\" | table Status Search App Schedule Runs \"Not run\" \"Avg run (s)\" \"Last run\" | search Status!=ok | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        },
        "refresh": "5m"
      }
    }
  },
